47	        this.firstName = firstName;
48	    }
49	
50	    public String getLastName() {
51	        return this.lastName;
52	    }
53	
54	    public void setLastName(String lastName) {
55	        this.lastName = lastName;
56	    }
57	
58	    /**
59	     * The upper-cased first letters of the first and last name, each followed by a
60	     * dot, e.g. {@code "J.S."} for John Smith.
61	     */
62	    @Transient
63	    public String getInitials() {
64	        return initial(this.firstName) + initial(this.lastName);
65	    }
66	
67	    private static String initial(String name) {
68	        return name.substring(0, 1).toUpperCase(Locale.ROOT) + ".";
69	    }
