2	
3	import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.delete;
4	import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
5	import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
6	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
7	
8	import java.nio.charset.StandardCharsets;
9	import java.security.MessageDigest;
10	import java.time.DayOfWeek;
11	import java.time.LocalDate;
12	import java.util.Map;
13	import java.util.Set;
14	import java.util.concurrent.atomic.AtomicInteger;
15	
16	import org.springframework.beans.factory.annotation.Autowired;
17	import org.springframework.boot.test.context.SpringBootTest;
18	import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
19	import org.springframework.http.MediaType;
20	import org.springframework.security.test.context.support.WithMockUser;
21	import org.springframework.test.web.servlet.MockMvc;
22	import org.springframework.test.web.servlet.ResultActions;
23	import org.springframework.transaction.annotation.Transactional;
24	
25	import tools.jackson.databind.JsonNode;
26	import tools.jackson.databind.ObjectMapper;
27	import tools.jackson.databind.node.ObjectNode;
28	
29	/**
30	 * Experimenter-owned, black-box acceptance base for PetClinic-Evolve.
31	 *
32	 * <p>Every checkpoint is a business rule on the ONE endpoint {@code POST /api/owners};
33	 * tests create owners and read fields back via {@code GET /api/owners/{id}}, so the
34	 * Spring and OfficeFloor arms are judged by identical externals.
35	 *
36	 * <p>Isolation: {@code @Transactional} rolls each test back, so count/quota rules
37	 * (membership number, per-day cap, per-city cap, "most common city") see only the
38	 * seed data plus what the test itself creates — deterministic without polluting
39	 * other tests. {@code @WithMockUser} authenticates as a fixed admin so the audit
40	 * rules can assert a known user name.
41	 *
42	 * <p>Cumulative-safety convention: {@link #ownerNode()} returns a FULLY UNIQUE
43	 * owner, which every rule accepts (no duplicate, no quota) at every checkpoint;
44	 * tests then override only the fields needed to trigger a specific rule. Reject
45	 * cases use data that stays rejected under all later (broader) rules.
46	 */
47	@SpringBootTest
48	@AutoConfigureMockMvc
49	@Transactional
50	@WithMockUser(username = "acceptance-admin", roles = {"OWNER_ADMIN", "VET_ADMIN", "ADMIN"})
51	public abstract class AcceptanceBase {
52	
53		private static final AtomicInteger SEQ = new AtomicInteger(0);
54	
55		@Autowired
56		protected MockMvc mvc;
57	
58		@Autowired
59		protected ObjectMapper om;
60	
61		protected int seq() {
62			return SEQ.incrementAndGet();
63		}
64	
65		// --- unique generators (avoid colliding with seed data or other tests) ---
66	
67		/** Encode n as a lowercase letter string (1->a, 26->z, 27->aa), so generated
68		 *  names satisfy the base app's letters-only owner-name pattern. */
69		protected String letters(int n) {
70			StringBuilder sb = new StringBuilder();
71			for (int x = Math.max(n, 1); x > 0; x /= 26) {
72				x--;
73				sb.insert(0, (char) ('a' + x % 26));
74			}
75			return sb.toString();
76		}
77	
78		/** Unique, letters-only surname (starts with "Sur"). */
79		protected String uniqueLastName() {
80			return "Sur" + letters(seq());
81		}
82	
83		/** Unique, letters-only given name (starts with "Fn"). Use this instead of names like
84		 *  "Mem"+i: the base app enforces a letters-only owner-name pattern, so a digit in a name is
85		 *  rejected with 400. Being unique it also keeps namesakeCount at 0. */
86		protected String uniqueFirstName() {
87			return "Fn" + letters(seq());
88		}
89	
90		protected String uniqueAddress() {
91			return seq() + " Test Street";
92		}
93	
94		protected String uniqueCity() {
95			return "Town" + seq();
96		}
97	
98		/** A unique 10-digit AU mobile ('04XXXXXXXX'). Chosen so the ONE payload stays valid across the
99		 *  whole telephone rule chain: 10 digits satisfies the early normalize-to-10 rule; dropping the
100		 *  leading '0' yields 9 national digits, which is exactly what the later E.164 '+61' form and the
101		 *  per-country length rule (+61 => 9 national digits) require. Distinct from the +1 NANP seed data. */
102		protected String uniqueTelephone() {
103			return String.format("04%08d", seq());
104		}
105	
106		protected String uniqueEmail() {
107			return "owner" + seq() + "@example.test";
108		}
109	
110		protected String today() {
111			return LocalDate.now().toString();
112		}
113	
114		// --- payloads -----------------------------------------------------------
115	
116		/** A fully valid, fully unique owner — accepted by every rule at every checkpoint. */
117		protected ObjectNode ownerNode() {
118			ObjectNode o = om.createObjectNode();
119			o.put("firstName", "Test");
120			o.put("lastName", uniqueLastName());
121			o.put("address", uniqueAddress());
122			o.put("city", uniqueCity());
123			o.put("telephone", uniqueTelephone());
124			return o;
125		}
126	
127		/** Owner payload plus a postcode. "2000" is in the NSW range and is accepted by cities with no
128		 *  known region (the permissive default), so it stays valid for the random cities ownerNode() makes. */
129		protected ObjectNode withPostcode(ObjectNode o) {
130			o.put("postcode", "2000");
131			return o;
132		}
133	
134		/** Owner with a STRUCTURED address (addressLine1 / city / postcode) for the later
135		 *  checkpoints that replace the flat 'address' input with structured fields. */
136		protected ObjectNode structuredOwner() {
137			ObjectNode o = ownerNode();
138			o.remove("address");
139			o.put("addressLine1", seq() + " Test Street");
140			o.put("postcode", "2000");
141			return o;
142		}
143	
144		// --- requests -----------------------------------------------------------
145	
146		protected String json(JsonNode node) {
147			try {
148				return om.writeValueAsString(node);
149			}
150			catch (Exception e) {
151				throw new RuntimeException(e);
152			}
153		}
154	
155		protected ResultActions createOwner(JsonNode body) throws Exception {
156			return mvc.perform(post("/api/owners").contentType(MediaType.APPLICATION_JSON)
157					.content(json(body)));
158		}
159	
160		protected int createOwnerOk(JsonNode body) throws Exception {
161			return extractId(createOwner(body).andExpect(status().is2xxSuccessful()));
162		}
163	
164		/** POST with an {@code Idempotency-Key} header (for the idempotent-create rule). */
165		protected ResultActions createOwnerWithKey(JsonNode body, String key) throws Exception {
166			return mvc.perform(post("/api/owners").contentType(MediaType.APPLICATION_JSON)
167					.header("Idempotency-Key", key).content(json(body)));
168		}
169	
170		/** Create {@code n} fully-unique owners (each accepted by every rule), all in the
171		 *  SAME city — used to drive the per-city capacity/warning rules. Returns nothing;
172		 *  each owner differs in name/address/telephone so only the city count accumulates. */
173		protected void fillCity(String city, int n) throws Exception {
174			for (int i = 0; i < n; i++) {
175				ObjectNode o = ownerNode();
176				o.put("city", city);
177				createOwnerOk(o);
178			}
179		}
180	
181		/** Create {@code n} fully-unique owners (each accepted by every rule), all dated
182		 *  today — used to drive the per-day create-limit / bulk-signup rules. */
183		protected void createMany(int n) throws Exception {
184			for (int i = 0; i < n; i++) {
185				createOwnerOk(ownerNode());
186			}
187		}
188	
189		protected ResultActions getOwner(int id) throws Exception {
190			return mvc.perform(get("/api/owners/" + id));
191		}
192	
193		/** Soft-delete an owner via DELETE /api/owners/{id} (asserts 2xx). The record is retained,
194		 *  flagged deleted, so the create endpoint's duplicate/identity checks ignore it. */
195		protected void deleteOwner(int id) throws Exception {
196			mvc.perform(delete("/api/owners/" + id)).andExpect(status().is2xxSuccessful());
197		}
198	
199		/** GET the owner and return its JSON body (asserts 2xx). */
200		protected JsonNode fetchOwner(int id) throws Exception {
201			String body = getOwner(id).andExpect(status().is2xxSuccessful())
202					.andReturn().getResponse().getContentAsString();
203			return om.readTree(body);
204		}
205	
206		protected int extractId(ResultActions ra) throws Exception {
207			String body = ra.andReturn().getResponse().getContentAsString();
208			if (body != null && !body.isBlank()) {
209				JsonNode n = om.readTree(body);
210				if (n.hasNonNull("id")) {
211					return n.get("id").asInt();
212				}
213			}
214			String location = ra.andReturn().getResponse().getHeader("Location");
215			if (location != null && location.contains("/")) {
216				return Integer.parseInt(location.substring(location.lastIndexOf('/') + 1));
217			}
218			throw new IllegalStateException("no id in create response: " + body);
219		}
220	
221		// --- pinned reference data ------------------------------------------------
222		// Shared, fixed ground truth for the LOOKUP-based rules (region, postcode,
223		// timezone, holidays). The rule specs enumerate these same tables, so both
224		// arms implement identical mappings and a test can assert an EXACT value
225		// (e.g. locality "NSW" for Sydney) instead of merely that a field exists.
226	
227		/** City -> canonical region; anything not listed derives locality "UNKNOWN". */
228		protected static final Map<String, String> CITY_REGION = Map.of(
229				"Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
230	
231		/** Region -> IANA timezone. */
232		protected static final Map<String, String> REGION_TIMEZONE = Map.of(
233				"NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
234	
235		/** Region -> inclusive 4-digit postcode range {low, high}. */
236		protected static final Map<String, int[]> REGION_POSTCODES = Map.of(
237				"NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
238	
239		/** Fixed public holidays the business-day roll skips (year of the run). */
240		protected static final Set<LocalDate> HOLIDAYS = Set.of(
241				LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
242				LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
243	
244		protected String region(String city) {
245			return CITY_REGION.getOrDefault(city, "UNKNOWN");
246		}
247	
248		protected String timezone(String city) {
249			return REGION_TIMEZONE.get(region(city));
250		}
251	
252		/** A postcode valid for the pinned city (low end of its region's range). */
253		protected String validPostcode(String city) {
254			int[] r = REGION_POSTCODES.get(region(city));
255			return r == null ? null : String.valueOf(r[0]);
256		}
257	
258		/** A fully-valid owner in a PINNED city with a valid postcode, so its region,
259		 *  timezone and postcode-derived values are known exactly. */
260		protected ObjectNode knownOwner(String city) {
261			ObjectNode o = ownerNode();
262			o.put("city", city);
263			o.put("postcode", validPostcode(city));
264			return o;
265		}
266	
267		/** Roll a date forward over weekends and pinned holidays to the next business day. */
268		protected LocalDate toBusinessDay(LocalDate d) {
269			while (d.getDayOfWeek() == DayOfWeek.SATURDAY || d.getDayOfWeek() == DayOfWeek.SUNDAY
270					|| HOLIDAYS.contains(d)) {
271				d = d.plusDays(1);
272			}
273			return d;
274		}
275	
276		// --- computed expectations ------------------------------------------------
277		// Tests replicate the spec's algorithms exactly so they can assert the precise
278		// derived value. The algorithms are standard (SHA-256, Luhn) and also stated in
279		// the specs, so both arms produce identical outputs.
280	
281		/** Full lower-case hex SHA-256 of the UTF-8 bytes of {@code s}. */
282		protected static String sha256hex(String s) {
283			try {
284				byte[] digest = MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));
285				StringBuilder sb = new StringBuilder(digest.length * 2);
286				for (byte b : digest) {
287					sb.append(String.format("%02x", b));
288				}
289				return sb.toString();
290			}
291			catch (Exception e) {
292				throw new RuntimeException(e);
293			}
294		}
295	
296		/** First {@code n} UPPER-case hex characters of SHA-256({@code s}). */
297		protected static String shaHex(String s, int n) {
298			return sha256hex(s).substring(0, n).toUpperCase();
299		}
300	
301		/** Luhn check digit (0-9) over the digits contained in {@code s}. */
302		protected static int luhn(String s) {
303			int sum = 0;
304			boolean dbl = true;
305			for (int i = s.length() - 1; i >= 0; i--) {
306				char c = s.charAt(i);
307				if (c < '0' || c > '9') {
308					continue;
309				}
310				int d = c - '0';
311				if (dbl) {
312					d *= 2;
313					if (d > 9) {
314						d -= 9;
315					}
316				}
317				sum += d;
318				dbl = !dbl;
319			}
320			return (10 - (sum % 10)) % 10;
321		}
322	}
